 if(action==='people-search'){const r=await api(`/api/people?q=${encodeURIComponent(d.q||'')}&language=${encodeURIComponent(d.language||'')}`);$('#people-results').innerHTML=r.people.map(p=>`<div class="card"><span class="avatar-small">${initials(p.full_name)}</span><h3 style="margin-top:12px">${esc(p.full_name)}</h3><p>@${esc(p.username||'')} · ${esc(p.level||'')}</p><div class="muted-sm">${(p.languages||[]).map(x=>x.toUpperCase()).join(' · ')}</div><button class="btn btn-primary btn-sm" style="margin-top:12px" data-action="friend-request" data-id="${p.id}">Gửi lời mời</button></div>`).join('')||empty('Không tìm thấy kết quả','Thử bộ lọc hoặc từ khóa khác.');return}
 if(action==='post-create'){await api('/api/community/posts',{method:'POST',body:d});toast('Đã đăng bài.');render();return}
